SELECT "nct", "author", "year", "originial_publication_or_follow_up", "trial_phase", "class_of_ici", "monotherapy_combination", "cancer_type", "name_of_ici", "treatment_regimen"
FROM public."clinical_trials"
WHERE "class_of_ici" = 'PD-L1' AND "cancer_type" = 'Colorectal' AND "trial_phase" = 'Phase 3' AND "monotherapy_combination" = 'Monotherapy';
